            aWandererI = aWandererI + (((RotL64(aCross, 10U) + RotL64(aOrbiterA, 19U)) + aOrbiterH) + RotL64(aCarry, 21U));
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 29U) + RotL64(aOrbiterA, 51U)) + aOrbiterG);
            aWandererD = aWandererD + (((RotL64(aScatter, 53U) + RotL64(aOrbiterK, 47U)) + aOrbiterB) + aWUSaltA[(((511U - aIndex) + 120U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aIngress, 57U) + RotL64(aOrbiterH, 5U)) + aOrbiterB);
            aWandererA = aWandererA + (((RotL64(aScatter, 43U) + aOrbiterG) + RotL64(aOrbiterI, 40U)) + aWUSaltE[(((511U - aIndex) + 467U)) & S_SALT1]);
            aWandererG = aWandererG ^ (((RotL64(aCross, 39U) + RotL64(aOrbiterJ, 57U)) + aOrbiterK) + aWUSaltF[((aIndex + 201U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aPrevious, 18U) + aOrbiterI) + RotL64(aOrbiterD, 23U)) + aWUSaltG[(((511U - aIndex) + 240U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 47U) + RotL64(aOrbiterA, 35U)) + aOrbiterI) + aWUSaltH[((aIndex + 280U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aScatter, 5U) + aOrbiterF) + RotL64(aOrbiterA, 12U)) + RotL64(aCarry, 29U));
            //
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererE, 34U));
