            //
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 39U) + aOrbiterA) + RotL64(aOrbiterH, 27U)) + aWUSaltA[(((511U - aIndex) + 297U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aIngress, 27U) + RotL64(aOrbiterC, 18U)) + aOrbiterK);
            aWandererI = aWandererI + (((RotL64(aCross, 13U) + RotL64(aOrbiterB, 23U)) + aOrbiterC) + aWUSaltH[((aIndex + 462U)) & S_SALT1]);
            aWandererF = aWandererF ^ ((RotL64(aScatter, 18U) + RotL64(aOrbiterH, 43U)) + aOrbiterG);
            aWandererK = aWandererK + (((RotL64(aPrevious, 43U) + RotL64(aOrbiterK, 3U)) + aOrbiterI) + RotL64(aCarry, 27U));
            aWandererH = aWandererH ^ ((RotL64(aIngress, 47U) + RotL64(aOrbiterG, 13U)) + aOrbiterF);
            aWandererC = aWandererC + (((RotL64(aCross, 53U) + RotL64(aOrbiterK, 37U)) + aOrbiterD) + aWUSaltB[(((511U - aIndex) + 292U)) & S_SALT1]);
            aWandererA = aWandererA ^ (((RotL64(aScatter, 58U) + aOrbiterA) + RotL64(aOrbiterB, 51U)) + aWUSaltE[((aIndex + 387U)) & S_SALT1]);
            aWandererB = aWandererB + ((((RotL64(aCross, 5U) + aOrbiterH) + RotL64(aOrbiterC, 56U)) + RotL64(aCarry, 11U)) + aWUSaltG[(((511U - aIndex) + 103U)) & S_SALT1]);
