            aOrbiterA = ((aWandererK + RotL64(aScatter, 47U)) + 0xED6CCBAC392857ACULL) + aOASaltB[((aIndex + 396U)) & S_SALT1];
            aOrbiterC = (((aWandererB + RotL64(aCross, 3U)) + RotL64(aCarry, 19U)) + 0x2502FCF0EDC60F4AULL) + aOASaltF[(((511U - aIndex) + 60U)) & S_SALT1];
            aOrbiterB = ((aWandererE + RotL64(aIngress, 57U)) + 0x3AEF50BCECDD9B0AULL) + aOASaltA[(((511U - aIndex) + 201U)) & S_SALT1];
            aOrbiterK = (((aWandererA + RotL64(aScatter, 27U)) + RotL64(aCarry, 53U)) + 0x769EF02F5FCADB03ULL) + aOASaltG[(((511U - aIndex) + 431U)) & S_SALT1];
            aOrbiterE = ((aWandererJ + RotL64(aPrevious, 41U)) + 0x67F3D0A369D036C0ULL) + aOASaltE[((aIndex + 418U)) & S_SALT1];
            //
            aOrbiterF = ((aOrbiterF + aOrbiterG) + 0x216571BF40D0986EULL) + aOUSaltG[(((511U - aIndex) + 246U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0xD439169FD9E2F3E7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x42E5E31CBF7DE171ULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0xF81575913BEE268EULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x8459C1DC6F832EC9ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xF819CFA22A6A9029ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0xE8F7229A8B7C3DEFULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterA) ^ 0x99E5B4CDC673233AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x785A9BF117AF6349ULL), 27U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterC) + 0x93F3C98D6C2CF252ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0x47EDF96745C49484ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x26563C7E8CCA191DULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x96195BFA992CEFDEULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterB) ^ 0xDD09851BE967EEF2ULL) ^ aOUSaltA[((aIndex + 351U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x46B72EF056D0C7D9ULL), 57U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x1EEC708F3606541AULL) + aOUSaltC[(((511U - aIndex) + 492U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0x1D88905EBF1C67E3ULL) ^ aOUSaltE[(((511U - aIndex) + 401U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x8D6033C46CC66975ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xEF9D0B15554D8575ULL;
