            aScatter = (RotL64(aPrevious, 10U) ^ RotL64(aCarry, 23U)) ^ (RotL64(aCross, 53U) + RotL64(aIngress, 37U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterG = (aWandererJ + RotL64(aPrevious, 47U)) + 0x73D905771D7374D1ULL;
            aOrbiterK = ((aWandererE + RotL64(aCross, 60U)) + 0x19032A3C32D04339ULL) + aOASaltE[(((511U - aIndex) + 466U)) & S_SALT1];
            aOrbiterE = ((aWandererC + RotL64(aIngress, 5U)) + 0x7371E91D9F44A9D6ULL) + aOASaltB[(((511U - aIndex) + 345U)) & S_SALT1];
            aOrbiterA = ((aWandererF + RotL64(aScatter, 13U)) + RotL64(aCarry, 41U)) + 0x168A78B4D9E4AEA5ULL;
            aOrbiterD = ((aWandererD + RotL64(aPrevious, 23U)) + 0xAE7AE4FEDE3027B3ULL) + aOASaltH[((aIndex + 325U)) & S_SALT1];
            aOrbiterB = (((aWandererB + RotL64(aIngress, 43U)) + RotL64(aCarry, 19U)) + 0xFDE15091BE5AACE4ULL) + aOASaltC[(((511U - aIndex) + 269U)) & S_SALT1];
            aOrbiterC = ((aWandererG + RotL64(aScatter, 51U)) + 0x7E85904CFC67F0B0ULL) + aOASaltG[((aIndex + 63U)) & S_SALT1];
            aOrbiterH = ((aWandererH + RotL64(aCross, 18U)) + RotL64(aCarry, 57U)) + 0xD62D9E2769070EF2ULL;
            aOrbiterI = (aWandererI + RotL64(aPrevious, 29U)) + 0x959FA3E88C605BBBULL;
            //
