            //
            aIngress = (RotL64(aShadowLaneA[((aIndex + 8377U)) & S_BLOCK1], 4U) ^ RotL64(aCrystalLaneC[((aIndex + 15712U)) & S_BLOCK1], 37U));
            aIngress ^= (RotL64(aFireLaneC[((aIndex + 13384U)) & S_BLOCK1], 57U) ^ RotL64(aWoodLaneA[((S_BLOCK1 - aIndex + 14121U)) & S_BLOCK1], 19U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
