            aWandererD = aWandererD + (((RotL64(aPrevious, 58U) + RotL64(aOrbiterB, 28U)) + aOrbiterH) + RotL64(aCarry, 29U));
            aWandererB = aWandererB ^ ((RotL64(aScatter, 21U) + aOrbiterK) + RotL64(aOrbiterA, 35U));
            aWandererG = aWandererG + ((RotL64(aCross, 37U) + aOrbiterE) + RotL64(aOrbiterJ, 43U));
