            aIngress ^= (RotL64(aWoodLaneA[((aIndex + 399U)) & S_BLOCK1], 60U) ^ RotL64(aPlasmaLaneB[((S_BLOCK1 - aIndex + 2687U)) & S_BLOCK1], 47U));
