            aScatter = (RotL64(aPrevious, 5U) + RotL64(aCross, 41U)) ^ (RotL64(aCarry, 57U) + RotL64(aIngress, 18U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = ((aWandererE + RotL64(aCross, 57U)) + 0x932CE29284B484D0ULL) + aOASaltC[((aIndex + 466U)) & S_SALT1];
            aOrbiterI = (aWandererG + RotL64(aIngress, 13U)) + 0x57F7933B6734B5B0ULL;
