            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0xFBB7E3656D512712ULL) ^ aOUSaltG[(((511U - aIndex) + 211U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x539EE3EC7D9FDCABULL), 39U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x28D39FD7E4FBE38EULL;
