            aOrbiterC = (aOrbiterC + aOrbiterD) + 0x9BF8109A7CEAC6A7ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0x6A87BE79F35205D1ULL) ^ aOUSaltF[((aIndex + 204U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xEF856F270B7C0DEFULL), 53U);
            //
            aIngress = RotL64(aOrbiterB, 27U) ^ aOrbiterK;
