            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterC, 10U));
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterI, 47U));
            aIngress = aIngress + (RotL64(aOrbiterA, 13U) ^ aOrbiterG);
            aIngress = aIngress + RotL64(aOrbiterJ, 21U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA + (((RotL64(aScatter, 40U) + RotL64(aOrbiterA, 48U)) + aOrbiterC) + RotL64(aCarry, 37U));
            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 19U) + aOrbiterB) + RotL64(aOrbiterG, 41U)) + aWUSaltD[(((511U - aIndex) + 348U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aPrevious, 35U) + aOrbiterI) + RotL64(aOrbiterK, 23U));
            aWandererB = aWandererB ^ ((RotL64(aCross, 29U) + RotL64(aOrbiterJ, 5U)) + aOrbiterH);
            aWandererH = aWandererH + ((RotL64(aPrevious, 23U) + RotL64(aOrbiterB, 39U)) + aOrbiterI);
