            aWandererF = aWandererF + (((RotL64(aPrevious, 5U) + RotL64(aOrbiterE, 3U)) + aOrbiterA) + aWUSaltF[((aIndex + 319U)) & S_SALT1]);
            aWandererD = aWandererD ^ (((RotL64(aScatter, 21U) + aOrbiterK) + RotL64(aOrbiterB, 19U)) + aWUSaltH[((aIndex + 111U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aCross, 27U) + RotL64(aOrbiterD, 11U)) + aOrbiterJ) + RotL64(aCarry, 21U));
            //
            aCarry = aCarry + (RotL64(aWandererG, 34U) ^ aWandererF);
