            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = ((aWandererB + RotL64(aScatter, 53U)) + RotL64(aCarry, 3U)) + 0x8DCB808B98441C98ULL;
            aOrbiterA = (((aWandererA + RotL64(aIngress, 47U)) + RotL64(aCarry, 27U)) + 0x1A933A956F383ACAULL) + aOASaltC[((aIndex + 283U)) & S_SALT1];
            aOrbiterC = ((aWandererE + RotL64(aCross, 35U)) + 0xB854224B169F92F2ULL) + aOASaltB[((aIndex + 227U)) & S_SALT1];
            aOrbiterG = (aWandererJ + RotL64(aPrevious, 5U)) + 0x8AD44771814F3034ULL;
            aOrbiterI = (aWandererH + RotL64(aCross, 22U)) + 0x084E210E8413A223ULL;
            aOrbiterF = (((aWandererK + RotL64(aPrevious, 11U)) + RotL64(aCarry, 39U)) + 0x76A3DDAA0D7D1CF3ULL) + aOASaltA[((aIndex + 215U)) & S_SALT1];
            aOrbiterD = ((aWandererG + RotL64(aIngress, 29U)) + 0x60A6D103C4CBEF10ULL) + aOASaltD[(((511U - aIndex) + 293U)) & S_SALT1];
