        // Ingress:
        //      aFuseLaneA (-->), aWindLaneC (-->), aMagmaLaneB (-->), aShadowLaneD (<-?->)
        //
        // Cross:
        //      aWindLaneD (<--), aWindLaneB (<--), aMagmaLaneA (<--), aCrystalLaneD (<-?->)
        //
        // Destination:
        //      aFuseLaneB
        //
