            aIngress ^= (RotL64(aMagmaLaneB[((aIndex + 14903U)) & S_BLOCK1], 57U) ^ RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 8656U)) & S_BLOCK1], 47U));
            aIngress = TwistMix64::DiffuseA((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 9648U)) & S_BLOCK1], 13U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 8394U)) & S_BLOCK1], 29U));
            aCross ^= (RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 11686U)) & S_BLOCK1], 39U) ^ RotL64(aCrystalLaneD[((aIndex + 8593U)) & S_BLOCK1], 54U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 19U) ^ RotL64(aIngress, 3U)) + (RotL64(aCarry, 40U) + RotL64(aPrevious, 53U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = (aWandererA + RotL64(aIngress, 53U)) + 0x4359B95B19070443ULL;
            aOrbiterB = ((aWandererH + RotL64(aPrevious, 11U)) + 0x9D4FAB0B808BBB48ULL) + aOASaltB[((aIndex + 114U)) & S_SALT1];
            aOrbiterG = (((aWandererC + RotL64(aCross, 19U)) + RotL64(aCarry, 41U)) + 0xC4E7D448F3FA9D0CULL) + aOASaltC[(((511U - aIndex) + 159U)) & S_SALT1];
            aOrbiterE = ((aWandererB + RotL64(aScatter, 41U)) + RotL64(aCarry, 27U)) + 0x102DA9B3EFB2ADFCULL;
            aOrbiterA = (((aWandererD + RotL64(aIngress, 35U)) + RotL64(aCarry, 5U)) + 0xD175E02FEDF1A61DULL) + aOASaltD[(((511U - aIndex) + 357U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aCross, 27U)) + 0x3A6EED8504943B3DULL) + aOASaltH[((aIndex + 235U)) & S_SALT1];
            aOrbiterK = ((aWandererJ + RotL64(aScatter, 60U)) + 0x85CB7A5A5C427DAEULL) + aOASaltF[((aIndex + 41U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x1238FA1BE9C292DBULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0x5A472BA3953AA089ULL) ^ aOUSaltH[((aIndex + 143U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x85549C7E5B95B6C7ULL), 57U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xBEC2D81081A127C0ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0x83823996E07DC38CULL;
