            aOrbiterC = (aOrbiterC + aOrbiterA) + 0xD7EDA1CD12024E55ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0x4C26CC22E7C2F418ULL) ^ aOUSaltA[((aIndex + 253U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xA472DC67EBEA2195ULL), 11U);
