            aWandererF = aWandererF + ((((RotL64(aScatter, 47U) + RotL64(aOrbiterJ, 37U)) + aOrbiterB) + RotL64(aCarry, 13U)) + aWUSaltA[(((511U - aIndex) + 417U)) & S_SALT1]);
