            aWandererJ = aWandererJ + (((RotL64(aIngress, 43U) + RotL64(aOrbiterC, 11U)) + aOrbiterG) + aWUSaltD[(((511U - aIndex) + 133U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aCross, 56U) + aOrbiterI) + RotL64(aOrbiterJ, 19U));
            //
            aCarry = aCarry + (RotL64(aWandererE, 56U) ^ aWandererJ);
