            aWandererI = aWandererI + ((((RotL64(aPrevious, 42U) + RotL64(aOrbiterD, 11U)) + aOrbiterJ) + RotL64(aCarry, 37U)) + aWUSaltH[((aIndex + 269U)) & S_SALT1]);
