            //
            aOrbiterG = ((aWandererI + RotL64(aCross, 19U)) + 0x9D9DA920A65F1BF6ULL) + aOASaltF[(((511U - aIndex) + 34U)) & S_SALT1];
            aOrbiterB = ((aWandererK + RotL64(aScatter, 37U)) + 0x508F718E18A3BD7AULL) + aOASaltD[((aIndex + 279U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aPrevious, 5U)) + 0x272BB01DA166FA65ULL;
            aOrbiterA = (aWandererH + RotL64(aIngress, 46U)) + 0xB3469511C6931ED6ULL;
            aOrbiterI = ((aWandererF + RotL64(aPrevious, 57U)) + RotL64(aCarry, 11U)) + 0x35146645038F265EULL;
            aOrbiterE = ((aWandererC + RotL64(aIngress, 11U)) + RotL64(aCarry, 29U)) + 0x5B41D326E8740831ULL;
            aOrbiterJ = (((aWandererA + RotL64(aScatter, 27U)) + RotL64(aCarry, 57U)) + 0x4632533037368FA6ULL) + aOASaltA[(((511U - aIndex) + 71U)) & S_SALT1];
