            aCross ^= (RotL64(aCrystalLaneB[((S_BLOCK1 - aIndex + 10396U)) & S_BLOCK1], 24U) ^ RotL64(aHeartLaneD[((aIndex + 13562U)) & S_BLOCK1], 47U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateBDomainWordCross));
            //
            aScatter = (RotL64(aCarry, 26U) + RotL64(aPrevious, 13U)) + (RotL64(aIngress, 57U) ^ RotL64(aCross, 41U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterA = (((aWandererK + RotL64(aScatter, 51U)) + RotL64(aCarry, 29U)) + 0x5D65F3301118C8C0ULL) + aOASaltH[((aIndex + 317U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aPrevious, 37U)) + 0x93DB17F385880DDFULL;
            aOrbiterC = ((aWandererH + RotL64(aCross, 4U)) + RotL64(aCarry, 3U)) + 0x5DF0ACAB7486FA61ULL;
            aOrbiterH = (((aWandererB + RotL64(aIngress, 23U)) + RotL64(aCarry, 53U)) + 0x8B7B3EF710C59D40ULL) + aOASaltA[((aIndex + 35U)) & S_SALT1];
            aOrbiterG = ((aWandererF + RotL64(aPrevious, 29U)) + 0xACE0F9FD077152DFULL) + aOASaltC[(((511U - aIndex) + 295U)) & S_SALT1];
            aOrbiterD = (aWandererJ + RotL64(aCross, 57U)) + 0x1A905F54870F15E5ULL;
            aOrbiterF = (aWandererD + RotL64(aIngress, 11U)) + 0xC962C5AD51B9027EULL;
